examples.code:
{/* A rise is good — the default. */}
<Kpi goodDirection="up">
  <Kpi.Trend value={7.8} />   {/* green */}
</Kpi>

{/* A fall is good. */}
<Kpi goodDirection="down">
  <Kpi.Trend value={-8.4} />  {/* also green */}
</Kpi>

{/* Neither. */}
<Kpi goodDirection="none">
  <Kpi.Trend value={2.2} />   {/* grey */}
</Kpi>
